// Header menus open on hover. After a click (which already changed the page) they close until the pointer leaves.
const hoverMenu = {
  onClick: (event: ReactMouseEvent<HTMLElement>) => { event.currentTarget.dataset.closed = "1"; (document.activeElement as HTMLElement | null)?.blur?.(); },
  onMouseLeave: (event: ReactMouseEvent<HTMLElement>) => { delete event.currentTarget.dataset.closed; },
};

