function AuthModal({ live, onClose, onSignedIn }: { live: boolean; onClose: () => void; onSignedIn: (session: UserSession, details?: Partial<Profile>) => void }) {
  const [mode, setMode] = useState<"login" | "create" | "verify">("login");
  const [email, setEmail] = useState("");
  const [remember, setRemember] = useState(true);
  const [pending, setPending] = useState<Partial<Profile>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [info, setInfo] = useState("");
  const [cooldown, setCooldown] = useState(0);
  const [social, setSocial] = useState<SocialProvider[]>([]);
  useEffect(() => { if (live) enabledSocialProviders().then(setSocial).catch(() => setSocial([])); }, [live]);
  useEffect(() => { if (!cooldown) return; const timer = window.setTimeout(() => setCooldown(cooldown - 1), 1000); return () => window.clearTimeout(timer); }, [cooldown]);
  const run = async (task: () => Promise<void>) => { setBusy(true); setError(""); setInfo(""); try { await task(); } catch (problem) { setError(problem instanceof Error ? problem.message : String(problem)); } finally { setBusy(false); } };
  const login = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const address = String(form.get("email")).trim(); setEmail(address); void run(async () => {
    try { onSignedIn(await signIn(address, String(form.get("password")), remember)); }
    catch (problem) { if (problem instanceof Error && /confirm your email/i.test(problem.message)) { setMode("verify"); setInfo("This email isn't confirmed yet. Enter the code we sent, or send a new one."); return; } throw problem; }
  }); };
  const create = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const address = String(form.get("email")).trim(); const password = String(form.get("password"));
    if (password !== String(form.get("confirm"))) { setError("The two passwords don't match."); return; }
    const dateProblem = birthdayProblem(String(form.get("birthday")) || null); if (dateProblem) { setError(dateProblem); return; }
    const details = { username: String(form.get("username")).trim(), birthday: String(form.get("birthday")) || null };
    setEmail(address); setPending(details);
    void run(async () => {
      const session = await signUp(address, password, { username: details.username }, remember);
      if (session) { onSignedIn(session, details); return; }
      setMode("verify"); setCooldown(60); setInfo(`Check ${address} for your confirmation email.`);
    });
  };
  const verify = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const code = String(new FormData(event.currentTarget).get("code")); void run(async () => { onSignedIn(await verifySignupCode(email, code, remember), pending); }); };
  const resend = () => void run(async () => { await resendSignupCode(email); setCooldown(60); setInfo(`A new confirmation email is on its way to ${email}.`); });
  const rememberBox = <label className="remember-me"><input type="checkbox" checked={remember} onChange={(event) => setRemember(event.target.checked)}/> Remember me on this device</label>;
  const messages = <>{error && <p className="auth-message error" role="alert">{error}</p>}{info && <p className="auth-message info" role="status">{info}</p>}</>;
  return <div className="modal-layer" onMouseDown={onClose}><section className="auth-modal login-redesign" role="dialog" aria-modal="true" aria-label="BH account" onMouseDown={(event) => event.stopPropagation()}><button className="icon auth-close" aria-label="Close" onClick={onClose}><X/></button><div className="login-brand"><b>BH</b><div><span><Sparkles size={16}/></span><span><Heart size={15}/></span><span><Gift size={16}/></span></div><p>MEMBERS GET MORE</p></div><div className="login-form">
    {!live ? <><p className="eyebrow"><UserRound size={14}/> BH ACCOUNT</p><h2>Accounts are<br/><em>offline</em><span>.</span></h2><p>This preview isn't connected to the store database, so signing in isn't available here.</p></>
    : mode === "verify" ? <><p className="eyebrow"><BadgeCheck size={14}/> VERIFY EMAIL</p><h2>One last<br/><em>step</em><span>.</span></h2><p>We sent an email to <b>{email}</b>. Click the confirmation link in it, or enter the code if the email shows one. It can take a minute to arrive; check your spam folder too.</p>{messages}<form onSubmit={verify}><label>Confirmation code<input name="code" required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6,8}" maxLength={8} placeholder="123456"/></label><button className="glow-button full" disabled={busy}>{busy ? "Checking…" : "Verify and continue"} <ArrowRight size={16}/></button></form><button className="auth-toggle" disabled={busy || cooldown > 0} onClick={resend}>{cooldown > 0 ? `Send the email again in ${cooldown}s` : <>Didn't get it? <b>Send the email again</b></>}</button><button className="auth-toggle" onClick={() => { setMode("login"); setError(""); setInfo(""); }}>Back to log in</button></>
    : <><p className="eyebrow"><UserRound size={14}/> BH ACCOUNT</p><h2>{mode === "login" ? <>Welcome<br/>back<span>.</span></> : <>Create your<br/><em>BH</em><span>.</span></>}</h2><p>{mode === "login" ? "Sign in to reach your profile and BH benefits." : "Create an account to save your profile, reviews and birthday reward. We'll email you a code to confirm it's you."}</p>{messages}
      {social.length > 0 && <><div className="social-buttons">{social.map((provider) => <a key={provider} className={`social-button ${provider}`} href={socialSignInUrl(provider)} onClick={() => rememberSocialChoice(remember)}><SocialMark provider={provider}/>Continue with {provider === "google" ? "Google" : provider === "facebook" ? "Facebook" : "Apple"}</a>)}</div><div className="auth-divider"><span>or with email</span></div></>}
      {mode === "login" ? <form onSubmit={login}><label>Email address<input name="email" required type="email" autoComplete="email" placeholder="you@email.com" defaultValue={email}/></label><label>Password<input name="password" required type="password" autoComplete="current-password" placeholder="Your password"/></label>{rememberBox}<button className="glow-button full" disabled={busy}>{busy ? "Signing in…" : "Log in"} <ArrowRight size={16}/></button></form>
      : <form onSubmit={create}><label>Username<input name="username" required minLength={3} maxLength={40} placeholder="Your name for reviews"/></label><label>Email address<input name="email" required type="email" autoComplete="email" placeholder="you@email.com" defaultValue={email}/></label><label>Date of birth<input name="birthday" type="date" min="1900-01-01" max={today()}/></label><label>Password<input name="password" required type="password" minLength={8} autoComplete="new-password" placeholder="At least 8 characters"/></label><label>Confirm password<input name="confirm" required type="password" minLength={8} autoComplete="new-password" placeholder="Repeat password"/></label>{rememberBox}<button className="glow-button full" disabled={busy}>{busy ? "Creating…" : "Create and verify email"} <ArrowRight size={16}/></button></form>}
      <button className="auth-toggle" onClick={() => { setMode(mode === "login" ? "create" : "login"); setError(""); setInfo(""); }}>{mode === "login" ? <>New to BH? <b>Create an account</b></> : <>Already have an account? <b>Log in</b></>}</button></>}
  </div></section></div>;
}

function Assistant({ onClose }: { onClose: () => void }) {
  const [mode, setMode] = useState<"start" | "faq" | "chat">("start");
  const [messages, setMessages] = useState([{ by: "bh", text: "Hi — I’m the BH Assistant. I can help you find a size, understand delivery or choose your next piece." }]);
  const [draft, setDraft] = useState("");
  const reply = (question: string) => { const lower = question.toLowerCase(); if (lower.includes("size")) return "For a relaxed BH fit, choose your usual size. Prefer a closer fit? Go one size down. Every product page includes XS–XL choices."; if (lower.includes("point")) return "BH Points arrive after an eligible purchase. You can use them as future cart credit or convert them into a BH Gift Card."; if (lower.includes("deliver") || lower.includes("ship")) return "Orders over $100 qualify for free international shipping. Once an order ships, its tracking appears in Orders & Shipments."; if (lower.includes("return")) return "You can request a return within 30 days of delivery for eligible, unworn pieces."; return "I can point you in the right direction. For order-specific support, tap WhatsApp below and the BH team will continue with you."; };
  const send = (text = draft) => { const clean = text.trim(); if (!clean) return; setMode("chat"); setMessages((current) => [...current, { by: "you", text: clean }, { by: "bh", text: reply(clean) }]); setDraft(""); };
  const quick = ["Help me find my size", "How do BH Points work?", "Delivery & tracking", "Returns & exchanges"];
  return <aside className="assistant-chat"><div className="assistant-head"><div><Sparkles size={18}/><div><b>BH Assistant</b><small>Fast answers, then real help</small></div></div><button className="icon" onClick={onClose}><X size={18}/></button></div>{mode === "start" && <div className="assistant-start"><span className="assistant-orb"><MessageCircle size={26}/></span><h2>How can BH<br/><em>help?</em><span>.</span></h2><p>Choose a quick answer or start a conversation.</p><button className="assistant-choice" onClick={() => setMode("faq")}><CircleHelp/><span><b>General questions</b><small>Sizes, points, delivery and returns</small></span><ArrowRight size={18}/></button><button className="assistant-choice" onClick={() => setMode("chat")}><MessageCircle/><span><b>Chat with BH</b><small>Ask anything about the store</small></span><ArrowRight size={18}/></button></div>}{mode === "faq" && <div className="assistant-faq"><button className="assistant-back" onClick={() => setMode("start")}><ChevronLeft size={16}/> Back</button><h3>Popular questions</h3>{quick.map((question) => <button key={question} onClick={() => { setMode("chat"); send(question); }}><span>{question}</span><ArrowRight size={15}/></button>)}</div>}{mode === "chat" && <><div className="assistant-thread">{messages.map((message, index) => <p key={index} className={message.by}>{message.text}</p>)}</div><div className="assistant-prompts">{quick.slice(0,3).map((prompt) => <button key={prompt} onClick={() => send(prompt)}>{prompt}</button>)}</div><form onSubmit={(event) => { event.preventDefault(); send(); }}><input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Ask BH anything…"/><button aria-label="Send message"><Send size={16}/></button></form></>}<div className="assistant-links"><a href="https://wa.me/" target="_blank" rel="noreferrer">Continue on WhatsApp</a><a href={"mailto:" + contactEmail}>Email BH</a></div></aside>;
}

function Info({ page, openInfo }: { page: InfoPage; openInfo: (page: InfoPage) => void }) {
  const pages = { about: ["About BH", "A wardrobe with a point of view.", "BH Clothing is built around elevated everyday pieces: better weight, better shape, and an easy way to wear your story. Anime is one of our collections, not the whole identity — it lives naturally beside the rest of the wardrobe."], faq: ["FAQ", "The useful answers.", "Shipping, returns, BH Points and sizing are kept simple. Need a personal answer? The BH Assistant can take you to WhatsApp or email."], terms: ["Terms & Conditions", "The clear version.", "These storefront terms are a design-stage placeholder. Before launch, BH will publish its final sales, delivery, returns and subscription terms for every market it serves."], privacy: ["Privacy", "Your details stay yours.", "This prototype does not process live payments or real account data. Before launch, BH will publish a complete privacy policy covering accounts, analytics, marketing and payment providers."] } as const;
  const [label, heading, copy] = pages[page];
  return <section className="info-page"><aside><p className="eyebrow">BH INFORMATION</p>{(["about","faq","terms","privacy"] as InfoPage[]).map((item) => <button key={item} className={page === item ? "active" : ""} onClick={() => openInfo(item)}>{pages[item][0]}<ArrowRight size={15}/></button>)}</aside><article><p className="eyebrow">{label}</p><h1>{heading}<span>.</span></h1><p>{copy}</p>{page === "faq" && <div className="faq-list">{[["Where do you ship?","BH is designed for international shipping. Delivery time and price appear at checkout."],["How do BH Points work?","Earn them after eligible purchases; use them later as cart credit or a BH Gift Card."],["Can I return something?","Eligible pieces can be requested for return within 30 days of delivery."]].map(([question, answer]) => <details key={question}><summary>{question}<ChevronDown size={16}/></summary><p>{answer}</p></details>)}</div>}</article></section>;
}
